// Builds the "PR QA" comment from the QA agent's output.
//
// The agent's output is untrusted (it was produced while reading
// pull-request content), so only files that pass validation are published and
// the summary is reduced to plain text.
//
// Usage: node publish.mjs <agent-output-dir> <publish-dir>
// Writes the validated assets and comment.md into <publish-dir>.
import fs from 'node:fs';
import path from 'node:path';

const [inputDir, publishDir] = process.argv.slice(2);
const { PR_NUMBER, HEAD_SHA, ASSET_BASE_URL, RUN_URL } = process.env;

const MARKER = '<!-- actual-bot-qa -->';
const SCREENSHOT = /^(before|after)-([a-z0-9]+(?:-[a-z0-9]+)*)\.png$/;
const MAX_PAIRS = 6;
const MAX_PNG_BYTES = 5 * 1024 * 1024;
const MAX_VIDEO_BYTES = 30 * 1024 * 1024;
const PNG_MAGIC = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const WEBM_MAGIC = Buffer.from([0x1a, 0x45, 0xdf, 0xa3]);

const VERDICTS = {
  pass: '✅ No problems found',
  'issues-found': '⚠️ Possible problems found',
  'not-applicable': 'ℹ️ Nothing to check in the app',
};

function readChecked(name, magic, maxBytes) {
  const file = path.join(inputDir, name);
  const stat = fs.lstatSync(file, { throwIfNoEntry: false });
  if (!stat?.isFile() || stat.size > maxBytes) return null;
  const data = fs.readFileSync(file);
  return data.subarray(0, magic.length).equals(magic) ? data : null;
}

// Plain text only: no HTML, links, images, mentions or issue references.
export function sanitize(value) {
  return String(value ?? '')
    .replace(/[\x00-\x08\x0b-\x1f\x7f\u200b-\u200f\u2028-\u202e]/g, '')
    .replace(/<[^>]*>/g, '')
    .replace(/\b[a-z][a-z0-9+.-]*:\/\/\S+/gi, '[link removed]')
    .replace(/\bwww\.\S+/gi, '[link removed]')
    .replace(/[<>[\]()!|`*_~#@\\]/g, '')
    .replace(/\s*\n\s*/g, ' ')
    .trim()
    .slice(0, 1500);
}

function build() {
  fs.mkdirSync(publishDir, { recursive: true });

  let result = {};
  try {
    result = JSON.parse(
      fs.readFileSync(path.join(inputDir, 'result.json'), 'utf8'),
    );
  } catch {
    // No usable result: reported below.
  }
  const verdict = Object.hasOwn(VERDICTS, result?.verdict)
    ? VERDICTS[result.verdict]
    : '❔ The QA session did not finish';
  const summary = sanitize(result?.summary);

  const names = fs.existsSync(inputDir) ? fs.readdirSync(inputDir).sort() : [];
  const pairs = new Map();
  for (const name of names) {
    const match = SCREENSHOT.exec(name);
    if (!match) continue;
    const data = readChecked(name, PNG_MAGIC, MAX_PNG_BYTES);
    if (!data) continue;
    if (!pairs.has(match[2]) && pairs.size >= MAX_PAIRS) continue;
    fs.writeFileSync(path.join(publishDir, name), data);
    pairs.set(match[2], { ...pairs.get(match[2]), [match[1]]: name });
  }

  const video = readChecked('after.webm', WEBM_MAGIC, MAX_VIDEO_BYTES);
  if (video) fs.writeFileSync(path.join(publishDir, 'after.webm'), video);

  const image = name =>
    name
      ? `<img src="${ASSET_BASE_URL}/${name}" width="420">`
      : '_not available_';

  const lines = [
    MARKER,
    `### 🤖 Automated QA: ${verdict}`,
    '',
    `Checked commit ${HEAD_SHA.slice(0, 7)} on the deploy preview against the current edge build.`,
    '',
    summary || '_No summary was produced._',
  ];
  if (pairs.size) {
    lines.push('', '| | Before | After |', '| --- | --- | --- |');
    for (const [name, pair] of pairs) {
      lines.push(`| ${name} | ${image(pair.before)} | ${image(pair.after)} |`);
    }
  }
  if (video) {
    lines.push('', `[Walkthrough video](${ASSET_BASE_URL}/after.webm)`);
  }
  lines.push(
    '',
    `<sub>Generated by an AI agent from untrusted pull request content. It can be wrong and is not a review or an approval. [Workflow run](${RUN_URL}) for #${PR_NUMBER}.</sub>`,
  );

  fs.writeFileSync(
    path.join(publishDir, 'comment.md'),
    `${lines.join('\n')}\n`,
  );
}

if (import.meta.url === `file://${process.argv[1]}`) build();
